mapper.select:
SELECT er.id, er.event_date AS eventDate, er.title, er.category_id AS categoryId, ec.name AS categoryName, ec.color AS categoryColor, er.note, er.level, er.created_at AS createdAt, er.updated_at AS updatedAt FROM event_record er INNER JOIN event_category ec ON ec.id = er.category_id AND ec.deleted = 0 WHERE er.deleted = 0 AND er.user_id = #{userId}
AND er.event_date >= #{startDate}
AND er.event_date <= #{endDate}
ORDER BY er.event_date ASC, er.created_at ASC

SELECT ec.id AS categoryId, ec.name AS categoryName, ec.color AS categoryColor, COUNT(er.id) AS count FROM event_record er INNER JOIN event_category ec ON ec.id = er.category_id AND ec.deleted = 0 WHERE er.deleted = 0 AND er.user_id = #{userId}
AND er.event_date >= #{startDate}
AND er.event_date <= #{endDate}
GROUP BY ec.id, ec.name, ec.color ORDER BY count DESC
